/// Tip topic for each tool (upstream TOOL_TOPICS; Square / Circle / Triangle share box).
pub const TOOL_TOPICS: &[(&str, &str)] = &[
    ("select", "select"),
    ("line", "line"),
    ("poly", "poly"),
    ("free", "free"),
    ("curve", "curve"),
    ("arc", "arc"),
    ("custom", "custom"),
    ("square", "box"),
    ("circle", "box"),
    ("triangle", "box"),
    ("funnel", "funnel"),
    ("text", "text"),
];

/// Finds a topic by id.
pub fn by_id(id: &str) -> Option<&'static Topic> {
    TOPICS.iter().find(|t| t.id == id)
}

/// Related topics for a topic (empty if absent from SEE).
pub fn see(id: &str) -> &'static [&'static str] {
    SEE.iter()
        .find(|(k, _)| *k == id)
        .map(|(_, v)| *v)
        .unwrap_or(&[])
}

/// The next topic shown after a tip is dismissed.
pub fn next(id: &str) -> Option<&'static str> {
    NEXT.iter().find(|(k, _)| *k == id).map(|(_, v)| *v)
}

/// Tool key (upstream tool name) -> tip topic id.
pub fn tool_topic(tool: &str) -> &'static str {
    TOOL_TOPICS
        .iter()
        .find(|(k, _)| *k == tool)
        .map(|(_, v)| *v)
        .unwrap_or("select")
}
